import torch
import torch.nn as nn
import torch.optim as optim
from torch.utils.data import TensorDataset, DataLoader
import torchattacks  # C&W 공격용

# A와 동일한 base model 구조 정의
class BaseModel(nn.Module):
    def __init__(self):
        super(BaseModel, self).__init__()
        self.conv1 = nn.Conv2d(3, 32, kernel_size=3, padding=1)
        self.pool = nn.MaxPool2d(2, 2)
        self.conv2 = nn.Conv2d(32, 64, kernel_size=3, padding=1)
        self.fc1 = nn.Linear(64 * 8 * 8, 256)
        self.fc2 = nn.Linear(256, 100)

    def forward(self, x):
        x = self.pool(torch.relu(self.conv1(x)))
        x = self.pool(torch.relu(self.conv2(x)))
        x = x.view(-1, 64 * 8 * 8)
        x = torch.relu(self.fc1(x))
        return self.fc2(x)

# model_cw 정의
device = torch.device('cuda' if torch.cuda.is_available() else 'cpu')
model_cw = BaseModel().to(device)
model_cw.load_state_dict(torch.load('base_model.pth'))
model_cw.eval()

# Dt_mis 데이터 로드
Dt_mis_inputs = torch.load("Dt_mis_inputs.pt")
Dt_mis_labels = torch.load("Dt_mis_labels.pt")

"""## **<C&W>**
![image.png](data:image/png;base64,)

-> FGSM보다 반복 최적화를 진해하기에 공격 강도가 매우 강력함 / 근데 느림
"""

# C&W 공격 정의
cw_attack = torchattacks.CW(model_cw, c=1, kappa=0, steps=1000, lr=0.01)

adv_inputs = []
adv_labels = []

adv_loader = DataLoader(TensorDataset(Dt_mis_inputs, Dt_mis_labels), batch_size=64, shuffle=False)

for inputs, labels in adv_loader:
    inputs, labels = inputs.to(device), labels.to(device)
    adv_x = cw_attack(inputs, labels)
    adv_inputs.append(adv_x.cpu())
    adv_labels.append(labels.cpu())

Dt_adv_inputs = torch.cat(adv_inputs, dim=0)
Dt_adv_labels = torch.cat(adv_labels, dim=0)

torch.save(Dt_adv_inputs, 'Dt_adv_inputs.pt')
torch.save(Dt_adv_labels, 'Dt_adv_labels.pt')
print("C&W 적대적 샘플 저장 완료")

"""######**model aprime -> 기존과 동일**#######"""

model_aprime = BaseModel().to(device)
model_aprime.load_state_dict(torch.load('base_model.pth'))

Dt_adv_dataset = TensorDataset(Dt_adv_inputs, Dt_adv_labels)
Dt_adv_loader = DataLoader(Dt_adv_dataset, batch_size=64, shuffle=True)

criterion = nn.CrossEntropyLoss()
optimizer = optim.Adam(model_aprime.parameters(), lr=0.001)

num_epochs = 10
model_aprime.train()
for epoch in range(num_epochs):
    running_loss = 0.0
    for inputs, labels in Dt_adv_loader:
        inputs, labels = inputs.to(device), labels.to(device)

        optimizer.zero_grad()
        outputs = model_aprime(inputs)
        loss = criterion(outputs, labels)
        loss.backward()
        optimizer.step()

        running_loss += loss.item()
    print(f"[A′ Epoch {epoch+1}] Loss: {running_loss:.3f}")

torch.save(model_aprime.state_dict(), 'a_prime_model.pth')
print("모델 저장 완료")
